(()=>{
 const uuid=()=>crypto.randomUUID?crypto.randomUUID():([1e7]+-1e3+-4e3+-8e3+-1e11).replace(/[018]/g,c=>(c^crypto.getRandomValues(new Uint8Array(1))[0]&15>>c/4).toString(16));
 const root=document.getElementById('hyper-cards');const q=s=>root.querySelector(s);let active='overview',products=[],cart=[],saleBusy=false,requestId=uuid(),lastReceipt=null,pendingSale=null;
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const fmt=(minor,currency)=>new Intl.NumberFormat('en-US',{minimumFractionDigits:currency==='USD'?2:0,maximumFractionDigits:currency==='USD'?2:0}).format(minor/(currency==='USD'?100:1));
 const qtyFmt=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:3}).format(n/1000);
 function message(text,error=false){q('#hs-notice').textContent=text;q('#hs-notice').setAttribute('role',error?'alert':'status');}
 async function api(path,options={}){return window.zhiroxRequest(path,options);}
 function icons(){window.lucide?.createIcons({attrs:{width:17,height:17}});}
 const btn=(text,action,primary=false)=>`<button type="button" class="btn ${primary?'primary':''}" data-foundation="${action}">${text}</button>`;
 function decimals(value,places,label){const clean=String(value).trim();if(!(places===0?/^\d+$/:new RegExp(`^\\d+(?:\\.\\d{1,${places}})?$`)).test(clean))throw new Error(`${label}: بڕێکی دروست بنووسە`);const [a,b='']=clean.split('.');const n=Number(a)*10**places+Number(b.padEnd(places,'0'));if(!Number.isSafeInteger(n))throw new Error(`${label}: بڕ زۆر گەورەیە`);return n;}
 async function catalog(){try{const result=await api('/api/products');products=result.products;if(active==='products')renderProducts();if(active==='pos')renderPOS();}catch(e){message(e.message,true);}}
 function renderProducts(){const view=q('#hs-view');view.innerHTML=`<section class="panel"><div class="toolbar"><input id="local-product-search" aria-label="گەڕانی کاڵا" placeholder="ناو، کۆد یان بارکۆد…">${btn('کاڵای نوێ','new-product',true)}</div><div class="tablewrap"><table><thead><tr><th>کاڵا / کۆد</th><th>بارکۆد</th><th>نرخی دانە</th><th>کارتۆن</th><th>بڕی بەردەست</th></tr></thead><tbody id="local-product-rows"></tbody></table></div><p class="sub">${products.length} کاڵای ڕاستەقینە · بڕی کۆگا بە دانەی بنەڕەتی</p></section>`;productRows('');if(!window.zhiroxAuth.can('products.write'))q('#hs-view').querySelector('[data-foundation="new-product"]').hidden=true;}
 function productRows(term){const rows=products.filter(p=>p.name.toLowerCase().includes(term.toLowerCase())||p.sku.toLowerCase().includes(term.toLowerCase())||p.barcodes.some(b=>b.code===term));q('#local-product-rows').innerHTML=rows.length?rows.map(p=>`<tr><td>${esc(p.name)}<div class="sub">${esc(p.sku)}</div></td><td>${p.barcodes.map(b=>`<div dir="ltr">${esc(b.code)} <span class="sub">${b.unit==='carton'?'کارتۆن':'دانە'}</span></div>`).join('')||'—'}</td><td>${fmt(p.unit_price,p.currency)} ${p.currency}</td><td>${p.carton_units} دانە<div class="sub">${fmt(p.carton_price,p.currency)} ${p.currency}</div></td><td>${qtyFmt(p.stock_milli)}</td></tr>`).join(''):'<tr><td colspan="5"><div class="empty"><strong>هیچ کاڵایەک نییە</strong>کاڵای ڕاستەقینە زیاد بکە؛ داتای نموونە تێدا نییە.</div></td></tr>';}
 function openProduct(){if(!window.zhiroxAuth.can('products.write')){message('دەسەڵاتی تۆمارکردنی کاڵات نییە',true);return;}q('#hs-modal-title').textContent='کاڵای نوێ';q('#hs-wizard-progress').innerHTML='';q('#hs-review').hidden=true;q('#hs-prev').hidden=true;q('#hs-save').hidden=true;const fields=q('#hs-fields');fields.innerHTML=`<form id="local-product-form" class="fields span">
 <label>ناوی کاڵا<input name="name" required maxlength="180"></label><label>کۆدی ناوخۆ<input name="sku" required maxlength="80"></label><label>دراو<select name="currency"><option>IQD</option><option>USD</option></select></label><label>نرخی دانە<input name="unit_price" inputmode="decimal" required value="0"></label><label>نرخی کڕینی دانە<input name="unit_cost" inputmode="decimal" required value="0"></label><label>ژمارەی دانە لە کارتۆن<input name="carton_units" type="number" min="1" max="100000" step="1" required value="1"></label><label>نرخی کۆی کارتۆن<input name="carton_price" inputmode="decimal" required value="0"></label><label>بڕی سەرەتایی بە دانە<input name="stock" inputmode="decimal" required value="0"></label><label class="span">بارکۆدەکانی دانە · بە کۆما جیا بکەرەوە<input name="unit_barcodes" dir="ltr" placeholder="00012345, 00067890"></label><label class="span">بارکۆدەکانی کارتۆن · بە کۆما جیا بکەرەوە<input name="carton_barcodes" dir="ltr"></label><div class="span actions"><button type="submit" class="btn primary">تۆمارکردنی کاڵا</button></div><div id="local-product-error" class="span" role="alert"></div></form>`;q('#hs-modal').hidden=false;root.classList.add('task-open');q('#hs-modal').querySelector('p.sub').textContent='تۆمارکردن لە داتابەیسی ناوخۆی ئەم کۆمپیوتەرە؛ هاوکاتکردنی کلاود چالاک نییە.';q('#hs-modal').scrollIntoView({block:'nearest'});}
 async function saveProduct(form){const button=form.querySelector('button[type=submit]');button.disabled=true;try{const data=Object.fromEntries(new FormData(form));const scale=data.currency==='USD'?2:0;const codes=(value,unit)=>value.split(/[,،\n]/).map(x=>x.trim()).filter(Boolean).map(code=>({code,unit}));const payload={name:data.name,sku:data.sku,currency:data.currency,unit_price:decimals(data.unit_price,scale,'نرخی دانە'),unit_cost:decimals(data.unit_cost,scale,'نرخی کڕین'),carton_units:Number(data.carton_units),carton_price:decimals(data.carton_price,scale,'نرخی کارتۆن'),stock_milli:decimals(data.stock,3,'بڕی سەرەتایی'),barcodes:[...codes(data.unit_barcodes,'unit'),...codes(data.carton_barcodes,'carton')]};await api('/api/products',{method:'POST',body:JSON.stringify(payload)});q('#hs-modal').hidden=true;root.classList.remove('task-open');message('کاڵاکە لە داتابەیسی ناوخۆ تۆمار کرا.');await catalog();}catch(e){q('#local-product-error').textContent=e.message;}finally{button.disabled=false;}}
 function renderPOS(){q('#hs-view').innerHTML=`<div class="toolbar"><input id="local-pos-search" aria-label="بارکۆد و گەڕانی کاشێر" placeholder="بارکۆد سکان بکە و Enter بدە، یان ناو بنووسە…"></div><div class="grid"><section class="panel"><h2>پسوولەی فرۆشتن</h2><div class="tablewrap"><table><thead><tr><th>کاڵا</th><th>یەکە</th><th>بڕ</th><th>کۆ</th><th></th></tr></thead><tbody id="local-cart"></tbody></table></div><div class="checkout"><div class="row"><span>کۆی گشتی</span><strong id="local-total">0</strong></div><label>پارەی وەرگیراو<input id="local-received" inputmode="decimal" value="0"></label><div class="row"><span>پارەی گەڕاوە</span><strong id="local-change">0</strong></div><button class="btn primary" id="local-pay">تۆمارکردنی فرۆشتن</button></div></section><section class="panel"><h2>ئەنجامی گەڕان</h2><div id="local-pos-products"></div></section></div>`;cartRows();posResults('');}
 function posResults(term){const matches=products.filter(p=>p.name.toLowerCase().includes(term.toLowerCase())||p.sku===term||p.barcodes.some(b=>b.code===term));q('#local-pos-products').innerHTML=matches.length?matches.map(p=>`<div class="entry"><div>${esc(p.name)}<div class="sub">${fmt(p.unit_price,p.currency)} ${p.currency} · کۆگا ${qtyFmt(p.stock_milli)}</div></div><button class="btn" data-add="${p.id}">زیادکردن</button></div>`).join(''):'<div class="empty">کاڵایەک نەدۆزرایەوە.</div>';}
 const total=()=>cart.reduce((s,x)=>s+x.quantity*(x.unit==='carton'?x.product.carton_price:x.product.unit_price),0);
 function cartRows(){q('#local-cart').innerHTML=cart.length?cart.map((x,i)=>`<tr><td>${esc(x.product.name)}</td><td><select data-cart-unit="${i}" aria-label="یەکەی ${esc(x.product.name)}"><option value="unit" ${x.unit==='unit'?'selected':''}>دانە</option><option value="carton" ${x.unit==='carton'?'selected':''}>کارتۆن · ${x.product.carton_units}</option></select></td><td><input class="small-quantity" data-cart-quantity="${i}" aria-label="بڕی ${esc(x.product.name)}" type="number" min="1" step="1" value="${x.quantity}"></td><td>${fmt(x.quantity*(x.unit==='carton'?x.product.carton_price:x.product.unit_price),x.product.currency)}</td><td><button class="btn" data-remove="${i}" aria-label="لابردنی ${esc(x.product.name)}">×</button></td></tr>`).join(''):'<tr><td colspan="5"><div class="empty">سەبەتە بەتاڵە.</div></td></tr>';q('#local-total').textContent=cart.length?`${fmt(total(),cart[0].product.currency)} ${cart[0].product.currency}`:'0';q('#local-pay').disabled=!cart.length||saleBusy;q('#local-received').disabled=Boolean(pendingSale);q('#local-cart').querySelectorAll('input,select,button').forEach(el=>el.disabled=Boolean(pendingSale));change();}
 function change(){if(!q('#local-change'))return;try{const currency=cart[0]?.product.currency||'IQD';const received=decimals(q('#local-received').value,currency==='USD'?2:0,'پارەی وەرگیراو');q('#local-change').textContent=received>=total()?`${fmt(received-total(),currency)} ${currency}`:'پارەکە کەمە';}catch{q('#local-change').textContent='بڕی پارە نادروستە';}}
 function add(id,unit='unit'){if(saleBusy||pendingSale)return;const p=products.find(p=>p.id===id);if(!p)return;if(cart.length&&cart[0].product.currency!==p.currency){message('دراوی کاڵاکان جیاوازە؛ پسوولەی جیا بۆ هەر دراوێک بەکاربهێنە.',true);return;}const existing=cart.find(x=>x.product.id===id&&x.unit===unit);if(existing)existing.quantity++;else cart.push({product:p,quantity:1,unit});requestId=uuid();cartRows();}
 async function pay(){if(saleBusy||!cart.length)return;try{const currency=cart[0].product.currency,received=decimals(q('#local-received').value,currency==='USD'?2:0,'پارەی وەرگیراو');if(received<total())throw new Error('پارەی وەرگیراو لە کۆی پسوولە کەمترە');saleBusy=true;cartRows();const payload={request_id:requestId,currency,received,items:cart.map(x=>({product_id:x.product.id,unit:x.unit,quantity:x.quantity}))};pendingSale=pendingSale||payload;const result=await api('/api/sales',{method:'POST',body:JSON.stringify(pendingSale)});pendingSale=null;lastReceipt=result.receipt;cart=[];requestId=uuid();message(`فرۆشتن تۆمار کرا؛ ژمارەی پسوولە ${lastReceipt.receipt_no}.`);await catalog();showReceipt(lastReceipt);}catch(e){if(e.responseReceived)pendingSale=null;message(pendingSale?'ئەنجامی ناردن دڵنیا نییە؛ دووبارە هەوڵبدە تا هەمان پسوولە پشتڕاست بکرێتەوە.':e.message,true);}finally{saleBusy=false;if(active==='pos'&&q('#local-pay')){q('#local-pay').disabled=!cart.length;q('#local-received').disabled=Boolean(pendingSale);q('#local-cart').querySelectorAll('input,select,button').forEach(el=>el.disabled=Boolean(pendingSale));}}}
 function showReceipt(receipt){let area=document.getElementById('receipt-print');if(!area){area=document.createElement('section');area.id='receipt-print';document.body.append(area);}area.innerHTML=`<h2>ZHIROX · پسوولەی فرۆشتن</h2><p>ژمارە: ${receipt.receipt_no} · <span dir="ltr">${esc(new Date(receipt.created_at).toLocaleString('en-GB',{timeZone:'Asia/Baghdad'}))}</span></p><table><thead><tr><th>کاڵا</th><th>بڕ</th><th>کۆ</th></tr></thead><tbody>${receipt.items.map(x=>`<tr><td>${esc(x.name)} · ${x.unit==='carton'?'کارتۆن':'دانە'}</td><td>${x.quantity}</td><td>${fmt(x.line_total,receipt.currency)}</td></tr>`).join('')}</tbody></table><p>کۆ: ${fmt(receipt.total,receipt.currency)} ${receipt.currency}</p><p>وەرگیراو: ${fmt(receipt.received,receipt.currency)} · گەڕاوە: ${fmt(receipt.change,receipt.currency)}</p><button id="local-print">چاپ</button><button id="local-receipt-close">داخستن</button>`;area.hidden=false;area.querySelector('#local-print').onclick=()=>window.print();area.querySelector('#local-receipt-close').onclick=()=>area.hidden=true;area.scrollIntoView({block:'nearest'});}
 window.zhiroxFoundation={openProduct,hasPendingSale:()=>Boolean(saleBusy||pendingSale),clearSession(){products=[];cart=[];pendingSale=null;lastReceipt=null;requestId=uuid();document.getElementById('receipt-print')?.remove();q('#hs-view').replaceChildren();q('#hs-fields').replaceChildren();},render(key){active=key;q('#hs-save').hidden=false;if(key!=='products')q('#hs-modal').querySelector('p.sub').textContent='پێشبینینی ڕووکارە؛ هیچ داتایەک لە سیستەم تۆمار ناکرێت.';if(key==='products'&&!window.zhiroxAuth.can('products.write'))q('#hs-actions').replaceChildren();if(key==='team')window.zhiroxAuth.renderTeam();if((key==='products'||key==='pos')&&window.zhiroxAuth.isReady())catalog();}};
 root.addEventListener('submit',event=>{if(event.target.id==='local-product-form'){event.preventDefault();saveProduct(event.target);}});
 root.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.foundation==='new-product')openProduct();if(b.dataset.add)add(b.dataset.add);if(b.dataset.remove!==undefined&&!saleBusy&&!pendingSale){cart.splice(Number(b.dataset.remove),1);requestId=uuid();cartRows();}if(b.id==='local-pay')pay();});
 root.addEventListener('input',event=>{if(event.target.id==='local-product-search')productRows(event.target.value);if(event.target.id==='local-pos-search')posResults(event.target.value);if(event.target.id==='local-received'&&!pendingSale){requestId=uuid();change();}});
 root.addEventListener('change',event=>{if(saleBusy||pendingSale)return;const i=event.target.dataset.cartUnit??event.target.dataset.cartQuantity;if(i!==undefined){if(event.target.dataset.cartUnit!==undefined)cart[Number(i)].unit=event.target.value;else{const value=Number(event.target.value);if(!Number.isSafeInteger(value)||value<1){message('بڕێکی دروست بنووسە',true);cartRows();return;}cart[Number(i)].quantity=value;}requestId=uuid();cartRows();}});
 root.addEventListener('keydown',event=>{if(event.target.id==='local-pos-search'&&event.key==='Enter'){event.preventDefault();const code=event.target.value.trim();const match=products.find(p=>p.barcodes.some(b=>b.code===code));if(match){const barcode=match.barcodes.find(b=>b.code===code);add(match.id,barcode.unit);event.target.value='';posResults('');}else message('بارکۆد نەدۆزرایەوە',true);}});
 // Keep unimplemented modules as the approved, clearly labelled preview.
 api('/api/health').then(()=>{}).catch(e=>message(e.message,true));
})();
